 void selected(File source)throws Exception{final Throwable[] error={null};m.runOnMainSync(()->{try{Method result=m.activity.getClass().getDeclaredMethod("onActivityResult",int.class,int.class,Intent.class);result.setAccessible(true);result.invoke(m.activity,4302,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(source)));}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);m.waitText("Импорт GeoTIFF");}
